function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must have the same length.';
  if (operations[0] !== 'DistanceLimitedPathsExist') return 'The first operation must be the constructor.';
  const [n, edgeList] = args[0];
  if (!Number.isInteger(n) || n < 2 || n > 10000) return 'n is between 2 and 10000.';
  if (!Array.isArray(edgeList) || edgeList.length > 10000) return 'edgeList has at most 10000 edges.';
  const node = (v) => Number.isInteger(v) && v >= 0 && v < n;
  const length = (v) => Number.isInteger(v) && v >= 1 && v <= 1000000000;
  for (const e of edgeList) {
    if (!Array.isArray(e) || e.length !== 3) return 'Each edge is [u, v, dis].';
    if (!node(e[0]) || !node(e[1]) || e[0] === e[1]) return 'Edge ends are two different nodes from 0 to n - 1.';
    if (!length(e[2])) return 'Edge lengths are between 1 and 10^9.';
  }
  if (operations.length - 1 > 10000) return 'At most 10000 queries.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'query') return 'Only query may follow the constructor.';
    const [p, q, limit] = args[i];
    if (!node(p) || !node(q) || p === q) return 'p and q are two different nodes from 0 to n - 1.';
    if (!length(limit)) return 'limit is between 1 and 10^9.';
  }
  return null;
}

