class DistanceLimitedPathsExist {
  constructor(n, edgeList) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank = new Array(n).fill(0);
    this.joinedAt = new Array(n).fill(Infinity);
    const edges = [...edgeList].sort((a, b) => a[2] - b[2]);
    for (const [u, v, dis] of edges) {
      let rootU = this.find(u, Infinity);
      let rootV = this.find(v, Infinity);
      if (rootU === rootV) continue;
      if (this.rank[rootU] < this.rank[rootV]) [rootU, rootV] = [rootV, rootU];
      this.parent[rootV] = rootU;
      this.joinedAt[rootV] = dis;
      if (this.rank[rootU] === this.rank[rootV]) this.rank[rootU]++;
    }
  }

  find(node, limit) {
    while (this.parent[node] !== node && this.joinedAt[node] < limit) {
      node = this.parent[node];
    }
    return node;
  }

  query(p, q, limit) {
    return this.find(p, limit) === this.find(q, limit);
  }
}

