class DistanceLimitedPathsExist {
  constructor(n, edgeList) {
    this.n = n;
    this.edges = edgeList.map(e => e.slice());
  }
  query(p, q, limit) {
    const reached = new Array(this.n).fill(false);
    reached[p] = true;
    let changed = true;
    while (changed) {
      changed = false;
      for (const [u, v, dis] of this.edges) {
        if (dis >= limit) continue;
        if (reached[u] !== reached[v]) { reached[u] = reached[v] = true; changed = true; }
      }
    }
    return reached[q];
  }
}

