function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 2 + Math.floor(rand() * 6);
  const m = large ? 1500 : Math.floor(rand() * 11);
  const maxWeight = large ? (rand() < 0.5 ? 1000000000 : 2000) : 1 + Math.floor(rand() * 10);
  const pick = () => Math.floor(rand() * n);
  const pair = () => { const a = pick(); let b = pick(); while (b === a) b = pick(); return [a, b]; };
  const edgeList = [];
  for (let i = 0; i < m; i++) {
    const [u, v] = pair();
    edgeList.push([u, v, 1 + Math.floor(rand() * maxWeight)]);
  }
  const operations = ['DistanceLimitedPathsExist'];
  const args = [[n, edgeList]];
  const queries = large ? 499 : 1 + Math.floor(rand() * 8);
  for (let i = 0; i < queries; i++) {
    const [p, q] = pair();
    operations.push('query');
    args.push([p, q, 1 + Math.floor(rand() * (maxWeight + 1))]);
  }
  return [operations, args];
}
